import { DATA } from "../data/dummyData";

type PageProps = {
  params: Promise<{
    state: string;
  }>;
};

export default async function StatePage({ params }: PageProps) {
  const { state } = await params; // ✅ FIX

  const cities = Object.keys(DATA[state] ?? {});

  return (
    <div className="min-h-screen p-4">
      <h1 className="text-lg font-semibold mb-4 capitalize">
        {state}
      </h1>

      {cities.map(city => (
        <a
          key={city}
          href={`/${state}/${city}`}
          className="block p-4 border rounded-xl mb-3 text-center capitalize"
        >
          {city}
        </a>
      ))}
    </div>
  );
}
